	// Only sync one agent manually (create symlink for tutor only)
	agentsDir := filepath.Join(filepath.Dir(sb.SourcePath), "agents")
	os.Symlink(
		filepath.Join(agentsDir, "tutor.md"),
		filepath.Join(claudeAgents, "tutor.md"),
